/** Flag cloth colour per course theme; unknown or missing themes fall back to the default. */
const THEME_FLAG_COLORS: Record<string, number> = {
  'green-hills': 0xe2573f,
  volcano: 0xff7a1a,
  'neon-city': 0xff2bd6,
  'haunted-mansion': 0x9b5de5,
  'space-station': 0x43d9ff,
  'candy-factory': 0xff8fc7,
  'pirate-bay': 0xf2c14e,
  'ancient-temple': 0xd9a441,
  'arctic-base': 0x7fdbff,
  'chaos-dimension': 0x7cf03d,
};

const CUP_COLOR = 0x14181d;
const CUP_LINER_COLOR = 0x0b0e12;
const FLAG_POLE_COLOR = 0xf1f3f5;
const DEFAULT_FLAG_COLOR = 0xe2573f;
const CUP_FLOOR_THICKNESS = 0.04;
const FLAG_POLE_HEIGHT = 1.1;
const FLAG_POLE_RADIUS = 0.022;
const FLAG_WIDTH = 0.42;
const FLAG_HEIGHT = 0.26;
const UNIT_SCALE: Vec3 = { x: 1, y: 1, z: 1 };

export interface HoleSceneResult {
  group: THREE.Group;
  meshCount: number;
  dispose(): void;
}

function applyTransform(mesh: THREE.Mesh, transform: TransformDescriptor, size: Vec3): void {
  mesh.position.set(transform.position.x, transform.position.y, transform.position.z);
  const rotation = transform.rotation;
  if (rotation) {
    mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
  }
  const scale = transform.scale ?? UNIT_SCALE;
  mesh.scale.set(size.x * scale.x, size.y * scale.y, size.z * scale.z);
}

/** Unit pennant: the hoist edge sits on x = 0, the tip points towards +x. */
function createFlagGeometry(): THREE.BufferGeometry {
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute([0, 0, 0, 0, 1, 0, 1, 0.5, 0], 3));
  geometry.setAttribute('normal', new THREE.Float32BufferAttribute([0, 0, 1, 0, 0, 1, 0, 0, 1], 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute([0, 0, 0, 1, 1, 0.5], 2));
  geometry.setIndex([0, 1, 2]);
  return geometry;
}

/** Turns a hole descriptor into renderable meshes backed by shared geometry and material caches. */
export class HoleSceneBuilder {
  private readonly boxGeometry: THREE.BoxGeometry;
  private readonly cylinderGeometry: THREE.CylinderGeometry;
  private readonly cupLinerGeometry: THREE.CylinderGeometry;
  private readonly flagGeometry: THREE.BufferGeometry;
  private readonly materials: Map<string, THREE.MeshStandardMaterial>;

  constructor() {
    this.boxGeometry = new THREE.BoxGeometry(1, 1, 1);
    this.cylinderGeometry = new THREE.CylinderGeometry(0.5, 0.5, 1, 24);
    this.cupLinerGeometry = new THREE.CylinderGeometry(0.5, 0.5, 1, 24, 1, true);
    this.flagGeometry = createFlagGeometry();
    this.materials = new Map();
  }

  /** themeId picks the flag colour; an unknown theme keeps the default cloth. */
  build(hole: Hole, themeId?: string): HoleSceneResult {
    const group = new THREE.Group();
    group.name = hole.id;

    for (const surface of hole.surfaces) {
      group.add(this.buildSurface(surface));
    }
    for (const obstacle of hole.obstacles) {
      group.add(this.buildObstacle(obstacle));
    }
    group.add(this.buildCup(hole, themeId));

    return {
      group,
      meshCount: group.children.length,
      dispose: () => {
        for (const child of group.children) {
          if (child instanceof THREE.Group) {
            child.clear();
          }
        }
        group.clear();
      },
    };
  }

  dispose(): void {
    this.boxGeometry.dispose();
    this.cylinderGeometry.dispose();
    this.cupLinerGeometry.dispose();
    this.flagGeometry.dispose();
    for (const material of this.materials.values()) {
      material.dispose();
    }
    this.materials.clear();
  }

  private buildSurface(surface: SurfaceDescriptor): THREE.Mesh {
    const geometry = surface.shape === 'cylinder' ? this.cylinderGeometry : this.boxGeometry;
    const mesh = new THREE.Mesh(
      geometry,
      this.materialFor('surface:' + surface.material, SURFACE_COLORS[surface.material]),
    );
    mesh.name = surface.id;
    applyTransform(mesh, surface.transform, surface.size);
    mesh.castShadow = false;
    mesh.receiveShadow = true;
    return mesh;
  }

  private buildObstacle(obstacle: ObstacleDescriptor): THREE.Mesh {
    const geometry = obstacle.type === 'pillar' ? this.cylinderGeometry : this.boxGeometry;
    const mesh = new THREE.Mesh(
      geometry,
      this.materialFor('obstacle:' + obstacle.type, OBSTACLE_COLORS[obstacle.type]),
    );
    mesh.name = obstacle.id;
    applyTransform(mesh, obstacle.transform, obstacle.size);
    mesh.castShadow = true;
    mesh.visible = obstacle.enabled !== false;
    return mesh;
  }

  /**
   * Cup assembly: the dark mouth marker, a recess lined down to a floor and the flag above it.
   * Everything lives in one child group, so a hole still reports one cup entry in its mesh count.
   */
  private buildCup(hole: Hole, themeId?: string): THREE.Group {
    const assembly = new THREE.Group();
    assembly.name = hole.id + '-cup-assembly';

    const center = hole.cup.position;
    const radius = hole.cup.radius;
    const diameter = radius * 2;
    const depth = Math.max(hole.cup.captureDepth, radius);

    const mouth = new THREE.Mesh(this.cylinderGeometry, this.materialFor('cup', CUP_COLOR));
    mouth.name = hole.id + '-cup';
    mouth.position.set(center.x, center.y, center.z);
    mouth.scale.set(diameter, radius, diameter);
    mouth.castShadow = false;
    mouth.receiveShadow = true;
    assembly.add(mouth);

    const liner = new THREE.Mesh(
      this.cupLinerGeometry,
      this.materialFor('cup-liner', CUP_LINER_COLOR, { side: THREE.BackSide }),
    );
    liner.name = hole.id + '-cup-liner';
    liner.position.set(center.x, center.y - depth / 2, center.z);
    liner.scale.set(diameter, depth, diameter);
    liner.castShadow = false;
    liner.receiveShadow = true;
    assembly.add(liner);

    const floor = new THREE.Mesh(this.cylinderGeometry, this.materialFor('cup-floor', CUP_LINER_COLOR));
    floor.name = hole.id + '-cup-floor';
    floor.position.set(center.x, center.y - depth + CUP_FLOOR_THICKNESS / 2, center.z);
    floor.scale.set(diameter, CUP_FLOOR_THICKNESS, diameter);
    floor.castShadow = false;
    floor.receiveShadow = true;
    assembly.add(floor);

    const pole = new THREE.Mesh(
      this.cylinderGeometry,
      this.materialFor('flag-pole', FLAG_POLE_COLOR, { roughness: 0.4, metalness: 0.2 }),
    );
    pole.name = hole.id + '-flag-pole';
    pole.position.set(center.x, center.y + FLAG_POLE_HEIGHT / 2, center.z);
    pole.scale.set(FLAG_POLE_RADIUS * 2, FLAG_POLE_HEIGHT, FLAG_POLE_RADIUS * 2);
    pole.castShadow = true;
    assembly.add(pole);

    const clothColor = THEME_FLAG_COLORS[themeId ?? ''] ?? DEFAULT_FLAG_COLOR;
    const flag = new THREE.Mesh(
      this.flagGeometry,
      this.materialFor('flag:' + clothColor, clothColor, { side: THREE.DoubleSide, roughness: 0.65 }),
    );
    flag.name = hole.id + '-flag';
    flag.position.set(center.x + FLAG_POLE_RADIUS, center.y + FLAG_POLE_HEIGHT - FLAG_HEIGHT, center.z);
    flag.scale.set(FLAG_WIDTH, FLAG_HEIGHT, 1);
    flag.castShadow = true;
    assembly.add(flag);

    return assembly;
  }

  private materialFor(
    key: string,
    color: number,
    options?: { side?: THREE.Side; roughness?: number; metalness?: number },
  ): THREE.MeshStandardMaterial {
    const cached = this.materials.get(key);
    if (cached) {
      return cached;
    }
    const material = new THREE.MeshStandardMaterial({
      color,
      roughness: options?.roughness ?? 0.85,
      metalness: options?.metalness ?? 0.05,
      side: options?.side ?? THREE.FrontSide,
    });
    material.name = key;
    this.materials.set(key, material);
    return material;
  }
}
